WITH filtered AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, COALESCE(channel, 'unassigned') channel_filled FROM promotions WHERE starts_on > DATE '2023-05-11') SELECT id, starts_on, LAG(discount_pct, 1, 0) OVER (PARTITION BY channel ORDER BY starts_on ASC, id ASC) prev_discount_pct, NTILE(10) OVER w_grp discount_pct_bucket, COUNT(discount_pct) OVER (PARTITION BY channel, promo_code) channel_count_discount_pct, NTILE(3) OVER w_running discount_pct_bucket_2, NTILE(4) OVER w_grp discount_pct_bucket_3 FROM filtered WHERE channel IN ('store', 'partner', 'mobile') WINDOW w_grp AS (PARTITION BY promo_code ORDER BY discount_pct ASC, id ASC), w_running AS (PARTITION BY promo_code ORDER BY discount_pct DESC, id ASC)
